import React from 'react';
// Official artwork with a shared blue tonal filter; see SERVICE-LOGOS.md.
export const serviceImages = {"eagle": "data:image/svg+xml;base64,", "feishu": "data:image/svg+xml;base64,"};
export const toolbarServiceImages = {"eagle": "data:image/svg+xml;base64,", "feishu": "data:image/svg+xml;base64,"};
export function ServiceLogo({name,tone="soft"}:{name:"eagle"|"feishu";tone?:"soft"|"white"}){return <img className="service-logo" src={(tone==="white"?toolbarServiceImages:serviceImages)[name]} width="22" height="22" alt="" aria-hidden="true"/>;}
